 navGroups[3].items=[['review','评分与复核','check'],['calibration','裁判校准','sliders'],['human','独立人工评测','users'],['regression','持续评测与回归','refresh'],['trends','质量趋势','chart']];
 navGroups[4].items=[['permissions','权限管理','users'],['cost','预算与成本','chart'],['resources','资源与接入','link'],['evolution','工作方式演进','branch'],['acceptance','验收案例','check'],['prd-review','PRD 对照与待确认','file']];
 save();
