function audit(kind,detail){state().audit.unshift({at:E.stamp(),actor:actor().name,kind,detail});save();}
function persist(){EvalUI.commit();save();}
function paint(){persist();render();}
function requireRole(...roles){if(!roles.includes(S.role))throw Error('此操作需要：'+roles.map(r=>E.actors[r]?.name||r).join(' / ')+'。请在右上角切换对应的已分配演示账号。');}
function requireMember(t,role){requireRole(role);if(t.prd.members[role]!==actor().id)throw Error('当前账号未分配为此任务的'+roleNames[role]+'角色。');}
function requireMutable(t){if(t.prd.manifest)throw Error('已冻结版本不可修改；请克隆为新的修订。');}
function invalidate(t){t.revision++;t.prd.pilot=null;t.prd.preflight=null;t.prd.confirmations={};t.prd.manifest=null;t.manifest=null;}
function intro(title,description,action=''){return `<div class="prd-intro"><div><div class="prd-eyebrow">AI EVALUATION / PRD 2026.10</div><h1>${title}</h1><p>${description}</p></div><div class="prd-actions">${action}</div></div>`;}
function scope(){return `<div class="prd-footer-note">交互稿 · 2026.10.29 · 合成回放 / 浏览器本地保存 · 未连接真实被测服务与生产权限系统。业务验收、真实数据和设备测试须单独执行。</div>`;}
function kpis(items,extra=''){return `<div class="prd-kpis ${extra}">${items.map(([n,v,s])=>`<div class="prd-kpi"><span>${n}</span><div class="number">${v}</div><small>${s||''}</small></div>`).join('')}</div>`;}
function demoCards(){return `<div class="prd-grid">${Object.entries(F).filter(([id,f])=>!f.legacy).map(([id,f])=>`<article class="prd-scene" style="--scene:${f.color}"><div class="between"><span class="prd-card-icon">${ic(f.icon)}</span><span class="prd-pill">${f.category}</span></div><h2>${h(f.name)}</h2><p>${h(f.description)}</p><div class="prd-taglist">${f.ac.map(a=>`<span>${a}</span>`).join('')}<span>可编辑输出</span></div><div class="prd-actions"><a class="btn" href="walkthrough.html?scene=${id}">步骤与准备包</a>${B('开始回放','create',id,'primary')}${B('查看案例','scene-info',id)}</div></article>`).join('')}</div>`;}
function overviewPage(){const rr=S.runs.filter(r=>r.prd),pending=rr.filter(r=>latest(r)?.summary.pending);return intro('让每个结论，都有证据可查','从一条目标开始，复用资产、冻结方案，完成评测与业务验收。',B('空白任务','create-blank','pdf')+B('从Demo创建','go','demos','primary'))+kpis([['本次交互更新','2026.10.29','2026-10-27 PRD 基线'],['新流程任务',tasks().length,'与原评测任务共用台账'],['待人工复核',pending.length,'复核未完成不发布通过结论'],['验收场景','20','主 PRD AC-01—20']])+panel('继续工作',taskTable(tasks().slice(-5).reverse()),B('全部任务','go','tasks'))+`<div class="prd-section"><div class="between"><h2>从业务场景开始</h2>${B('查看全部 Demo','go','demos')}</div></div>`+demoCards()+scope();}
function demosPage(){return intro('场景 Demo',Object.values(F).filter(f=>!f.legacy).length+' 条可回放路径：编辑证据 → 试评 → 双角色确认 → 冻结 → 运行 → 复核与报告。',B('验收案例','go','acceptance')+'<a class="btn primary" href="walkthrough.html">完整操作文档、流程图与视频</a>')+info('每个 Demo 提供异常、正确、缺证和解析器故障数据。结果由当前字段与固定规则计算，不等于真实模型效果。')+demoCards()+panel('推荐演示顺序',`<ol><li>以评测负责人创建 PDF 任务，保存目标和对象。</li><li>核验输入与独立参考，确认 Demo 口径，运行试评和预检。</li><li>切换业务负责人确认当前方案，再由评测负责人冻结并运行。</li><li>查看 FAIL 与待复核并存；切换质量审核完成复核，生成新快照。</li><li>克隆修订、载入正确证据，重跑后对照新旧报告。</li></ol>`)+scope();}
function taskTable(ts){return tableP(['任务 / 对象','方案版本','权限包','状态','操作'],ts.map(t=>[`${h(t.name)}<div class="prd-muted">${h(t.object)} · ${h(t.objectVersion||'版本待补充')}</div>`,t.id+' · r'+t.revision,h(t.prd.package?.name||'分类待匹配')+' @'+(t.prd.package?.version||'—'),tag(t.prd.runId?(L.status(findRun(t.prd.runId)).businessComplete?'业务已完成':findRun(t.prd.runId)?.state||'DRAFT'):t.prd.manifest?'FROZEN':'DRAFT'),B('打开任务','task',t.id)]));}
function tasksPage(){const historical=S.evalTasks.filter(t=>!t.prd);return intro('评测任务','需求可以不完整；正式冻结前逐项补齐。历史任务保留原始版本。',B('空白任务','create-blank','pdf')+B('从Demo创建','go','demos','primary'))+panel('当前 PRD 流程',taskTable(tasks().slice().reverse()))+panel('历史任务',tableP(['任务','来源','操作'],historical.map(t=>[h(t.name||t.goal),'<span class="prd-muted">旧版交互数据，未自动升级审批或门槛</span>',B('查看历史','legacy-task',t.id)])))+scope();}
function createTask(scene=null,blank=false,seed={}){
 if(window.PlazaReview)return window.PlazaReview.createTask(scene,blank,seed);
 const f=!blank&&F[scene]||null,type=seed.type||f?.category||'待明确',department=f?.department||'企业业务';
 const m=E.matchPackage({department,type},state().rules,state().packages);
 const t=EvalUI.core.task({name:f?.name||seed.object||'未命名评测',goal:f?.input.request||f?.input.goal||f?.description||'',object:f?.object||'',objectVersion:f?.version||'',objectProof:{kind:'build',ref:f?.proof||''},type,budget:f?10:null,source:'PRD V17',executionScope:f?'DEMO_REPLAY_ONLY':'UNCONFIGURED',...seed});
 t.prd={scene:f?scene:null,step:0,department,classification:department+'/'+type,outputs:E.clone(f?.output||{}),metricIds:[...(f?.metrics||[])],supportedMetrics:[...(f?.metrics||[])],inputReady:false,samplePolicy:null,connectionVerified:!!f,entry:f?'内置回放':'待选择',package:m.pack||null,rule:m.rule||null,ruleVersion:state().ruleVersion,matchReason:m.reason,members:{engineer:E.actors.engineer.id,business:E.actors.business.id,quality:E.actors.quality.id,expert:E.actors.expert.id},confirmations:{},assemblyMode:'DIRECT',contentMode:type==='Agent'?'CASE':'DATASET',taskTypeRef:'',dependencies:f?[{id:'INPUT-'+scene,version:1,hash:E.hash(f.input),scope:'SYNTHETIC_REPLAY_ONLY'},{id:'RULES-'+scene,version:1,hash:E.hash(f.checks),scope:'SYNTHETIC_REPLAY_ONLY'}]:[]};
 L.configureTask(t);S.evalTaskId=t.id;persist();go('prd-task');return t;
}
function genericData(t){const p=t.prd,available=EvalUI.core.list().filter(a=>a.status==='已发布'&&((a.targets||[]).includes(t.type)||p.dependencies.some(d=>d.key===EvaluationCore.key(a))));
 return panel('按当前需求组装',info('当前没有绑定 Demo 数据。任务类型与资产引用可先保存；真实目录、能力匹配及接入尚未验证，不能正式运行。','warn')+`<div class="prd-fields">${input('任务类型精确版本引用','p-task-type',p.taskTypeRef||'')}${select('资产组装方式','p-assembly',[['DIRECT','直接组装（DIRECT）'],['SUITE','复用套件（SUITE）']],p.assemblyMode||'DIRECT')}${select('评测内容','p-content',[['DATASET','数据集样本'],['CASE','用例 / 用例库']],p.contentMode||'DATASET')}</div><fieldset class="prd-choice"><legend>复用已发布资产 · 精确版本</legend>${available.length?assetGroups.map(g=>`<details class="prd-asset-group" ${available.some(a=>g.types.some(([k])=>k===a.kind)&&p.dependencies.some(d=>d.key===EvaluationCore.key(a)))?'open':''}><summary>${h(g.name)} · ${available.filter(a=>g.types.some(([k])=>k===a.kind)).length}</summary>${available.filter(a=>g.types.some(([k])=>k===a.kind)).map(a=>`<label class="checkline"><input type="checkbox" name="p-dependency" value="${h(EvaluationCore.key(a))}" ${p.dependencies.some(d=>d.key===EvaluationCore.key(a))?'checked':''}>${h(a.name)} · ${h(a.version)} · ${h(a.type||a.kind)}</label>`).join('')}</details>`).join(''):'<p>当前对象类型下暂无可复用的已发布资产。</p>'}</fieldset><div class="prd-taglist">${p.metricIds.map(id=>`<span>${h(id)}${B('移除','metric-remove',id)}</span>`).join('')}</div><div class="prd-actions">${B('保存组装草稿','assembly-save','','primary')}${B('建设或补齐资产','go','assets')}${B('选择指标','go','metrics')}${B('执行预检','preflight')}</div>`)+panel('演示当前类型的完整流程',info('以下选项是合成业务案例，载入后会替换本任务的数据、指标与输出，并清除旧确认；不表示平台仅支持这些任务类型。')+select('选择合成 Demo','p-demo-scene',[['','请选择'],...Object.entries(F).filter(([k,x])=>!x.legacy&&x.category===t.type).map(([k,x])=>[k,x.name])],'')+`<div class="prd-actions">${B('预览并载入 Demo','load-demo-preview')}</div>`)+(p.preflight?panel('当前预检缺口',tableP(['缺口','负责人'],p.preflight.gaps.map(g=>[h(g.text),h(g.owner)]))):'');
}
function importPanel(t,f){const p=t.prd,c=p.externalConfig||{},file=x=>p.files?.[x]?info('已导入：'+h(p.files[x].name)+' · SHA256 '+h(p.files[x].sha256)):'';return panel('文件与外部接入',info('可上传准备包中的输入、源文件和接入配置。JSON内容与文件摘要随方案冻结；PDF等源文件仅登记摘要，当前不解析或长期托管文件。','warn')+`<p><a class="btn" href="walkthrough.html?scene=${h(p.scene)}" target="_blank" rel="noopener">查看此场景准备与步骤</a></p><div class="prd-fields"><label>上传输入 JSON<input class="input" type="file" data-walk-upload="input" accept=".json"></label><label>上传源文件或证据附件<input class="input" type="file" data-walk-upload="source" multiple></label><label>上传接入配置 JSON<input class="input" type="file" data-walk-upload="connection" accept=".json"></label></div>${file('input')}${file('connection')}${(p.sourceFiles||[]).map(x=>info(h(x.name)+' · '+x.size+' 字节 · SHA256 '+h(x.sha256))).join('')}<details ${c.kind?'open':''}><summary>平台外准备如何接入</summary><p>先在外部准备模型/自动化代码、固定版本、Schema与独立观测，再配置以下引用。当前只做字段契约核对；真实连通性、授权、执行器资格仍未验证。</p><div class="prd-fields">${select('外部接入类型','w-kind',['API','网页','容器','可执行程序','SDK'],c.kind||'API')}${input('服务或网页入口','w-endpoint',c.endpoint||'')}${input('运行命令 / 镜像入口','w-command',c.command||c.image||c.entrypoint||'')}${input('外部对象精确版本','w-version',c.objectVersion||t.objectVersion)}${input('适配器版本','w-adapter',c.adapterVersion||'')}${input('输入 Schema 引用','w-input-schema',c.inputSchemaRef||'')}${input('输出 Schema 引用','w-output-schema',c.outputSchemaRef||'')}${input('凭证引用（不要填密钥）','w-auth',c.authRef||'none')}${input('超时（毫秒）','w-timeout',c.timeoutMs||30000,'number')}</div>${B('保存接入配置','save-connection','','primary')}${c.kind?'<details><summary>已导入的完整接入映射</summary>'+dump(c)+'</details>'+info('已保存 '+h(c.kind)+' 接入契约；执行模式：外部证据回放；真实连接未验证。','warn'):''}</details>`);}
async function importTaskFile(e){const kind=e.target.dataset?.walkUpload;if(!kind)return;try{const t=current();requireMember(t,'engineer');requireMutable(t);const p=t.prd,files=[...e.target.files];if(!files.length)return;if(files.some(f=>f.size>5*1024*1024))throw Error('演示文件单个不超过5MB；原文件请留在本地。');const entries=[];for(const file of files){const bytes=await file.arrayBuffer(),sha256=WalkthroughContracts.sha256(bytes);entries.push({meta:{name:file.name,size:file.size,sha256,at:E.stamp()},text:kind==='source'?null:new TextDecoder().decode(bytes)});}if(current()?.id!==t.id||t.prd.manifest)throw Error('任务已切换或冻结，请重新打开草稿导入。');p.files=p.files||{};const x=entries[0];if(kind==='source'){p.sourceFiles=entries.map(x=>x.meta);}else{let raw;try{raw=JSON.parse(x.text);}catch{throw Error('JSON格式错误；原数据保持。');}if(kind==='connection'){p.externalConfig=WalkthroughContracts.connection(raw,p.scene);p.taskTypeRef=p.externalConfig.taskTypeVersionRef||p.taskTypeRef;p.externalEvidenceMode=true;p.entry='内置回放';p.connectionVerified=true;}else if(kind==='input'){const payload=WalkthroughContracts.unwrap(raw,'input',p.scene);if(Object.keys(F[p.scene].input).some(k=>!(k in payload)))throw Error('输入缺少当前场景要求的字段，请核对输入Schema。');p.importedInput=payload;p.inputReady=false;p.dependencies=p.dependencies.filter(d=>d.id!=='UPLOADED-INPUT');p.dependencies.push({id:'UPLOADED-INPUT',version:1,hash:x.meta.sha256,scope:'SYNTHETIC_REPLAY_ONLY'});}else p.outputs=WalkthroughContracts.unwrap(raw,'output',p.scene);p.files[kind]={...x.meta,receipt:{requestId:raw.requestId||raw.request_id||null,traceId:raw.traceId||raw.trace_id||null,synthetic:raw.synthetic===true,fixtureVersion:raw.fixtureVersion||null}};}invalidate(t);paint();toast('文件已读取并登记；原文件内容不会上传到外部服务。','success');}catch(error){modal('文件导入未完成',info(h(error.message),'warn'),B('关闭','close'));}}
document.addEventListener('change',importTaskFile);
const steps=['需求与对象','数据与指标','试评与预检','确认与冻结','运行与证据','复核与报告'];
function taskPage(){const t=current();if(!t)return intro('选择一项任务','先创建或打开任务。',B('打开任务列表','go','tasks','primary'));const p=t.prd,f=taskFixture(t);return intro(h(t.name),`${t.id} · 方案 r${t.revision} · ${h(t.objectVersion||'对象版本待补充')}`,B('任务列表','go','tasks')+B('克隆新修订','clone',t.id))+`<nav class="prd-steps" aria-label="评测步骤">${steps.map((s,i)=>`<button data-prd="step" data-key="${i}" ${p.step===i?'aria-current="step"':''}><b>${i+1}</b>${s}</button>`).join('')}</nav>`+info(h(f?.limit||'从需求开始，逐项补齐对象、任务类型、数据、指标与执行能力。'),'warn')+taskSteps(t,f)+scope();}
function taskSteps(t,f){const p=t.prd;if(!f&&p.step>0)return genericData(t);switch(p.step){
case 0:return panel('从目标与对象开始',`<div class="prd-fields">${input('任务名称','p-name',t.name)}${input('被测对象','p-object',t.object)}${input('评测目标','p-goal',t.goal)}${input('精确版本','p-version',t.objectVersion)}${input('构建 / 配置证明（URL不替代版本）','p-proof',t.objectProof?.ref)}${input('本次预算上限（元，合成）','p-budget',t.budget,'number')}${select('需求部门','p-department',['企业业务','车载研发'],p.department)}${select('对象类型','p-type',['待明确','模型','Agent','非Agent应用'],t.type)}${select('接入方式','p-entry',['待选择','内置回放','API','网页','容器','可执行程序','SDK'],p.entry)}</div><div class="prd-actions">${B('保存草稿','save-task','','primary')}${B('下一步','step','1')}</div><p class="prd-help">空缺允许保存。未配置的真实入口会在预检明确阻断；不会回退至外部服务。</p>`)+panel('权限绑定与人员',info(`${h(p.matchReason)} · ${h(p.package?.name||'未匹配')} @${p.package?.version||'—'} / 规则 v${p.ruleVersion}。任务不自行选择更宽松的权限包。`)+`<div class="prd-fields">${['engineer','business'].map(role=>select(role==='engineer'?'评测负责人账号':'业务负责人账号','p-member-'+role,Object.values(E.actors).map(a=>[a.id,a.name]),p.members[role])).join('')}</div><div class="prd-actions">${B('保存人员','members','','primary')}${B('预览迁移到现行配置','migration-preview')}</div><p class="prd-help">两项确认需不同账号；包版本发布不会自动升级存量任务。</p>`);
case 1:return importPanel(t,f)+`<div class="prd-dual">${panel('输入与请求',dump(f.input),B('下载输入','download-input',t.id))}${panel('独立评分参考',tableP(['检查点','指标','冻结参考'],f.checks.map(c=>[h(c.name),h(c.metric),h(JSON.stringify(c.expected))])),tag('SYNTHETIC'))}</div>`+panel('准备与统计约定',`<label class="checkline"><input id="p-input-ready" type="checkbox" ${p.inputReady?'checked':''}>已核对合成输入与独立参考；正式运行须替换为获准、固定版本资产。</label><label class="checkline"><input id="p-policy" type="checkbox" ${p.samplePolicy?'checked':''}>同意本 Demo 的逐检查点口径；所有数值门槛仅用于回放，未经生产批准。</label><p class="prd-help">1 次计划业务试验；${f.checks.length} 个强制检查单元。技术 attempt 不新增分母。未判定项不补零。</p><div class="prd-taglist">${p.metricIds.map(id=>`<span>${id}${!f.metrics.includes(id)?B('移除','metric-remove',id):''}</span>`).join('')}</div><div class="prd-actions">${B('保存数据与口径','data-ready','','primary')}${B('查看独立指标目录','go','metrics')}${B('下一步','step','2')}</div>`);
case 2:return panel('导入平台外运行结果',`<p>在平台外运行数据包中的 runner.py，上传生成的输出；本页面校验并评分，不会主动访问所填服务。</p><label>上传原始输出 JSON<input class="input" type="file" data-walk-upload="output" accept=".json"></label>${p.files?.output?info('已导入：'+h(p.files.output.name)+' · SHA256 '+h(p.files.output.sha256)) : ''}`)+panel('编辑待回放的原始输出',`<div class="prd-actions">${B('异常样例','variant','mixed')}${B('正确样例','variant','correct')}${B('必要证据缺失','variant','missing')}${B('解析器故障','variant','parser')}</div><label class="prd-copy">原始输出 JSON<textarea id="p-output" class="input prd-code" rows="12">${h(JSON.stringify(p.outputs,null,2))}</textarea></label><div class="prd-actions">${B('保存输出','output-save','','primary')}${B('运行试评','pilot')}${B('执行预检','preflight')}</div><p class="prd-help">修改输出会使原试评、预检和确认失效。试评核验正例、负例、缺证与解析失败分支；产品输出失败不等于试评机制失败。</p>`)+panel('当前预检',p.preflight?info(`${tag(p.preflight.status)} 方案摘要 ${h(p.preflight.digest)} · ${fmt(p.preflight.at)}`)+(p.preflight.gaps.length?tableP(['缺口','负责人'],p.preflight.gaps.map(g=>[h(g.text),h(g.owner)])):info('当前方案无阻断缺口，可进入业务确认。','success')):info('尚未预检；预检不预占真实设备。'))+(p.pilot?panel('试评输出',rowTable(p.pilot.rows)+info('评分器分支核验完成；必要复核和统计证明仍独立约束最终结论。')):'')+`<div class="prd-actions">${B('下一步','step','3')}</div>`;
case 3:return panel('业务确认摘要',tableP(['核对项','当前方案'],[['评测目标',h(t.goal)],['被测对象',h(t.object)+' · '+h(t.type)],['范围与限制',h(f.limit)],['验收条件',f.checks.map(c=>h(c.name)+'：'+h(JSON.stringify(c.expected))).join('<br>')],['试评结果',p.pilot?tag(E.aggregate(p.pilot.rows).verdict)+' · 已确认失败 '+E.aggregate(p.pilot.rows).failures+' 项':'尚未试评']])+info('请核对目标、适用范围、强制条件和试评异常；确认的是当前方案，不是提前判定质量通过。'))+panel('确认当前精确方案',tableP(['固定项','当前值'],[['方案摘要',E.planHash(t)],['对象版本',h(t.objectVersion)],['输入与参考',p.dependencies.map(d=>d.id+'@'+d.version+' / '+d.hash).join('<br>')],['权限绑定',h(p.package?.name||'缺失')+' @'+p.package?.version+' / 规则 v'+p.ruleVersion],['统计口径',p.samplePolicy?h(p.samplePolicy.text):'尚未确认'],['业务确认',p.confirmations?.business?`${h(p.confirmations.business.name)} · ${h(p.confirmations.business.digest)}`:'待任务业务负责人确认'],['冻结状态',p.manifest?tag('FROZEN')+' '+p.manifest.id:'待评测负责人冻结']])+`<div class="prd-actions">${B('业务确认当前方案','business-confirm','','primary')}${B('评测负责人冻结','freeze')}${B('下一步','step','4')}</div>`+info('使用右上角切换演示账号。平台管理员不自动拥有业务批准、资产发布或预算审批权。'));
case 4:{const r=findRun(p.runId);return panel('运行与证据',info(`冻结清单：${p.manifest?h(p.manifest.id):'尚未冻结'}。启动时重新检查授权、方案摘要与预算。`)+`<div class="prd-actions">${B('启动合成回放','start','','primary')}${r&&['RUNNING','INTERRUPTED'].includes(r.state)?B('停止并查询状态','cancel',r.id,'danger'):''}</div>`+(r?runBody(r):'<div class="prd-empty">尚无运行；完成冻结后可开始。</div>'))+`<div class="prd-actions">${B('打开报告','step','5')}</div>`;}
case 5:{const r=findRun(p.runId);return r?reportBody(r):panel('复核与报告','<div class="prd-empty">尚未产生结果快照，请先运行。</div>');}
}}
function rowTable(rows){return tableP(['本地断言 / 指标（非PRD案例编号）','单项判定','有效性 / 复核','原始值 → 参考','证据'],rows.map(r=>[h(r.name)+'<div class="prd-muted">'+h(r.id)+' / '+h(r.metric)+'</div>',tag(r.judgment),tag(r.validity)+(r.reviewPending?' · 待人工复核':''),h(JSON.stringify(r.actual))+' → '+h(JSON.stringify(r.expected)),h(r.evidence)+'<div class="prd-muted">'+h(r.reason)+'</div>']));}
function mayReport(r,action='report.read'){try{return L.authorizeReport(r,tasks().find(t=>t.id===r.taskId),actor(),action);}catch{return false;}}
function statePanel(r){const x=WalkthroughContracts.terminal(r);return panel('六项独立状态',kpis([['执行进度',x.execution||r.state,'系统执行 / 停止新派发'],['质量结论',mayReport(r)?x.quality||latest(r)?.summary.verdict||'NOT_EVALUATED':'权限受限','必要复核与质量门禁保持'],['业务验收',x.business||r.businessAcceptance?.status||'PENDING','接受 / 有条件接受 / 退回'],['环境清理',x.environment||r.environment,'已获准连接器自动清理并验证'],['费用核查',x.cost||r.settlement,'系统采集用量、批准价格幂等结算'],['报告导出',x.report||'历史未记录','按权限按需导出，不阻塞完成']], 'prd-lifecycle-kpis')+info(h(x.label))+info('下一步：'+h(x.next||'历史记录只读；新修订按现行流程验证。')));}
function exceptionPanel(r){const open=(r.issues||[]).filter(x=>x.status==='OPEN');return open.length?panel('仅异常转人工待办',tableP(['异常','负责人','操作'],open.map(x=>[h(x.reason),h(x.owner),x.category==='TECHNICAL'&&actor().permissions?.includes('technical.recover')&&r.technicalOwners.includes(actor().id)?B('技术修复后重试自动处理','reconcile',r.id):x.category==='COST_POLICY'&&actor().permissions?.includes('cost.policy')&&r.costOwners.includes(actor().id)?B('应用已批准价格并重试','cost-policy-retry',r.id):'由对应权限人员处理']))) : info('系统收尾无技术异常；无需运维参与。','success');}
function runBody(r){const sn=latest(r);return statePanel(r)+(sn&&mayReport(r)?rowTable(sn.rows):info(r.state==='RUNNING'?'合成执行器正在运行，系统将在回执到达后自动计量、清理并核查费用。':sn?'当前账号没有报告读取范围。':'尚无质量快照；取消和技术恢复不生成质量通过结论。'))+exceptionPanel(r);}
function reportBody(r){const sn=latest(r),terminal=WalkthroughContracts.terminal(r);if(!mayReport(r))return statePanel(r)+info('报告访问受限：需要报告动作权限，以及当前任务和数据范围授权。运维角色本身不授予报告访问或导出权。','warn')+exceptionPanel(r);if(!sn)return statePanel(r)+info('尚无质量快照可导出；未导出不阻止取消流程完成。')+exceptionPanel(r);const a=sn.summary;return statePanel(r)+exceptionPanel(r)+panel('结果快照 · r'+sn.revision,info(`${tag(a.verdict)} <strong>${h(a.label)}</strong> · 已确认强制失败 ${a.failures} 项；待复核 ${a.pending?'是':'否'}。`,a.verdict==='PASS'?'success':a.verdict==='BLOCK'?'danger':'warn')+rowTable(sn.rows)+`<div class="prd-actions">${a.pending&&['quality','expert'].includes(S.role)?B('完成必要人工复核','review-complete',r.id,'primary'):''}${mayReport(r,'report.export')?B('按需导出报告 JSON','export-report',r.id):''}${mayReport(r,'evidence.export')?B('按需导出证据包','export-evidence',r.id):''}${S.role==='engineer'?B('重新评分追加快照','rescore',r.id):''}</div>`+info('费用核查、技术恢复、业务接受和报告导出均不改写质量结论。必要复核保持；补证或修订输出须新修订重跑。'))+panel('业务验收',S.role==='business'&&current()?.prd.members.business===actor().id?select('验收决定','p-acceptance',[['ACCEPTED','接受'],['CONDITIONAL','有条件接受'],['RETURNED','退回整改']],r.businessAcceptance?.status||'RETURNED')+input('原因 / 条件','p-acceptance-reason',r.businessAcceptance?.reason||'')+B('业务负责人记录验收','acceptance-record',r.id)+(r.businessAcceptance?info(h(r.businessAcceptance.status)+' · '+h(r.businessAcceptance.reason)):'')+info('业务方只确认接受或退回；不负责清理、复位、计价或结算。'):info(r.businessAcceptance?h(r.businessAcceptance.status)+' · '+h(r.businessAcceptance.reason):'等待任务业务负责人记录接受或退回；费用待核查及报告未导出不阻塞本动作。'))+panel('不可变历史',tableP(['快照','时间','结论','覆盖'],r.prdSnapshots.map(x=>[x.id,fmt(x.at),tag(x.summary.verdict),x.summary.coverage.effective+'/'+x.summary.coverage.applicable])));}
function appendSnapshot(r,rows){const revision=(r.prdSnapshots||[]).length+1;const sn={id:r.id+'-SN-'+revision,revision,runId:r.id,comparisonUnit:r.taskId,published:true,at:E.stamp(),rows:E.clone(rows),summary:E.aggregate(rows),scope:'SYNTHETIC_REPLAY_ONLY',manifest:E.clone(r.prdManifest)};r.prdSnapshots=r.prdSnapshots||[];r.prdSnapshots.push(sn);r.verdict=sn.summary.verdict;return sn;}
function runsPage15(){return intro('运行与证据','状态、环境、结算与质量结论分别记录；历史数据不自动转为新验收。')+panel('新流程运行',tableP(['运行 / 任务','执行状态','质量结论','操作'],S.runs.filter(r=>r.prd).map(r=>[h(r.id)+'<div class="prd-muted">'+h(r.name)+'</div>',tag(r.state),tag(latest(r)?.summary.verdict||'PENDING'),B('查看证据与报告','report',r.id)])))+panel('历史运行',tableP(['运行','原状态','操作'],S.runs.filter(r=>!r.prd).map(r=>[h(r.id)+' · '+h(r.name),h(r.state),B('查看旧版记录','legacy-run',r.id)])))+scope();}
function reviewPage15(){return intro('评分与复核','单项判定、有效性、总体门禁和业务验收采用不同字段。')+info('必要人工复核未完成 → INCONCLUSIVE；复核完成后，任一有效强制失败 → BLOCK；仅缺证 → INCONCLUSIVE；全部适用要求、资格与统计条件满足 → PASS。')+panel('待复核记录',tableP(['运行','当前门禁','已确认失败','操作'],S.runs.filter(r=>r.prd&&latest(r)?.summary.pending).map(r=>[r.id,tag('INCONCLUSIVE'),latest(r).summary.failures,B('进入复核','report',r.id)])))+panel('专项资格',`<div class="prd-actions">${B('裁判校准','go','calibration')}${B('独立人工评测','go','human')}${B('覆盖率趋势','go','trends')}</div><p>普通资产双人确认不会替代新可执行能力验证、裁判资格与盲评独立性要求。</p>`)+scope();}
function metricsPage(){const ms=D.metrics.filter(m=>(!window.NavigationUI||NavigationUI.isExample()||m.id[0]!=='B')&&(!metricDimension||m.dimension===metricDimension)&&(!metricGroup||(metricGroup==='platform'?m.id[0]==='M':m.id[0]==='B'))&&(!metricQuery||(m.id+m.name+m.formula).toLowerCase().includes(metricQuery.toLowerCase())));return intro('独立指标目录','候选定义与任务阈值分开管理；目录条目不等于已批准的生产门槛。',(window.FlowUI?.metricDirectoryReturn()||(directoryTask()?B('返回原任务 '+h(directoryTaskId),'metric-return'):B('打开评测任务列表','go','tasks'))))+kpis(window.NavigationUI&&!NavigationUI.isExample()?[['平台口径',String(D.metrics.filter(m=>m.id[0]==='M').length),'参考定义，需绑定实现后执行'],['当前筛选',String(ms.length),'查看下方定义与证据']]:[['平台指标','45','M01—M45'],['业务配置','25','B01—B25'],['独立候选','56','45 + 11；另14项复用'],['质量维度','9','不做等权单一总分']])+`<div class="prd-toolbar"><label>检索指标<input id="p-metric-query" class="input" value="${h(metricQuery)}" placeholder="编号、名称、计算方式"></label>${select('维度','p-metric-dimension',[['','全部维度'],...[...new Set(D.metrics.map(m=>m.dimension))].filter(Boolean)],metricDimension)}${select('目录','p-metric-group',[['','全部条目'],['platform','平台指标'],...(!window.NavigationUI||NavigationUI.isExample()?[['business','业务配置']]:[])],metricGroup)}${B('应用筛选','metric-filter')}</div>`+panel('指标条目 · '+ms.length,tableP(['编号 / 名称','维度','计算口径','状态 / 操作'],ms.map(m=>[h(m.id)+' · '+h(m.name),h(m.dimension||'业务场景配置'),h(m.formula),`<span class="prd-pill">候选 · 阈值待确认</span><div class="prd-actions">${B('定义与证据','metric-detail',m.id)}${directoryTask()?B('加入来源草稿','metric-add',m.id):''}</div>`])))+scope();}
function acceptancePage(){const cs=[...D.cases,...(D.reviewCases||[])].filter(c=>!caseQuery||(c.id+c.title+c.expected).includes(caseQuery));return intro('验收案例','主 PRD AC-01—20 与本轮 UX-01—13 修复验收分别记录；原型通过不替代生产验收。','<a class="btn" href="responsive.html" target="_blank" rel="noopener">响应式验收</a>'+B('导出验收包','export-cases','','primary'))+info('以下是验收步骤与预期。自动测试覆盖原型规则；真实账号、设备、内网接入、文件处理和业务数据验收尚未执行。','warn')+`<div class="prd-toolbar"><label>查找案例<input id="p-case-query" class="input" placeholder="AC编号或关键词" value="${h(caseQuery)}"></label>${B('筛选','case-filter')}</div>`+cs.map(c=>`<details class="prd-case"><summary><b>${h(c.id)}</b><span>${h(c.title)}</span><span class="prd-pill">${h(state().caseResults[c.id]?.status||'待验收')}</span></summary><div class="prd-case-body"><h3>前置条件</h3><p>${h(c.given)}</p><h3>验收步骤</h3>${c.steps?'<ol>'+c.steps.map(x=>'<li>'+h(x)+'</li>').join('')+'</ol>':''}<ol ${c.steps?'hidden':''}><li>打开对应页面或Demo，核对当前版本与适用范围。</li><li>按以下预期分别操作正常、缺证与权限受限路径。</li><li>保留运行 / 快照 / 原始证据编号，记录差异与复验结论。</li></ol><h3>预期结果</h3>${c.requirement?'<p>依据：'+h(c.requirement)+'</p>':''}<p class="prd-expected">${h(c.expected)}</p>${c.verification?info('本轮定向复验：'+h(c.verification)):''}<div class="prd-actions">${B('打开对应交互','case-open',c.id,'primary')}${B('记录验收结果','case-record',c.id)}</div>${state().caseResults[c.id]?info(h(state().caseResults[c.id].status)+' · '+h(state().caseResults[c.id].evidence)):''}</div></details>`).join('')+scope();}
