function trendsPage(){const all=S.runs.flatMap(r=>r.prdSnapshots||[]),a=E.trend(all,E.stamp()),pass=all.filter(s=>s===latest(findRun(s.runId))&&s.summary.verdict==='PASS').length;return intro('质量趋势','每个运行取截至时点最新发布快照，再取同一比较单元最新记录；所有结论均参与覆盖统计。')+kpis([['有效覆盖',a.ratio===null?'—':(a.ratio*100).toFixed(1)+'%',a.effective+' / '+a.applicable+'（汇总计数）'],['比较单元',a.snapshots.length,'同单元取最新记录'],['PASS运行',pass,'覆盖率不等于通过率'],['统计时间',new Date().toLocaleDateString('zh-CN'),'截至当前快照']])+panel('AC-13 口径示例',tableP(['快照','单项','有效 / 适用','门禁'],[['r1','FAIL有效 + UNKNOWN缺证','1 / 2 = 50%','BLOCK'],['r2补证','FAIL有效 + PASS有效','2 / 2 = 100%','BLOCK']]))+info('有效FAIL贡献覆盖但不贡献通过；可选项、重复项与技术重试不增加强制分母。仅有冻结批准且注明原因的NOT_APPLICABLE可排除；分母为0显示空值。')+panel('采用的快照',tableP(['运行','快照','门禁','覆盖'],a.snapshots.map(s=>[s.runId,s.id,tag(s.summary.verdict),s.summary.coverage.effective+'/'+s.summary.coverage.applicable])))+scope();}
