window.addEventListener('click',e=>{const old=e.target.closest('[data-v2]');if(old&&['new','template','create','from-asset'].includes(old.dataset.v2)){e.preventDefault();e.stopImmediatePropagation();try{requireRole('engineer');EvalUI.forceClose();if(old.dataset.v2==='create'){const goal=val('v2-goal'),object=val('v2-object');if(!goal&&!object)throw Error('请填写评测需求或被测对象，至少填写一项。');createTask(null,true,{goal,object,type:val('v2-type'),objectVersion:val('v2-version')});}else if(old.dataset.v2==='from-asset'){const a=EvalUI.core.find(old.dataset.key);const n=createTask(null,true,{name:'基于 '+a.name+' 的评测',object:a.object||'',type:a.targets?.length===1?a.targets[0]:'待明确'});n.prd.dependencies=[{key:EvaluationCore.key(a),id:a.id,version:a.version,hash:EvaluationCore.digest(a)}];paint();}else createTask(old.dataset.v2==='template'?(old.dataset.key==='office'?'pdf':old.dataset.key==='front'?'edge':F[old.dataset.key]?old.dataset.key:null):null,old.dataset.v2==='new');}catch(err){toast(err.message,'error');}return;}const b=e.target.closest('[data-prd]');if(!b||b.disabled)return;e.preventDefault();e.stopImmediatePropagation();Promise.resolve(handle(b.dataset.prd,b.dataset.key||'')).catch(err=>{toast(err.message||String(err),'error');});},true);
